cause.patch:
diff --git a/Caddyfile b/Caddyfile
@@ -1,5 +1,8 @@
 {
 	email {$ACME_EMAIL}
+	# Staging CA while new site names are tested: failed attempts do not count
+	# against the production rate limit of Let's Encrypt
+	acme_ca https://acme-staging-v02.api.letsencrypt.org/directory
 	# The admin API is not needed: configuration changes go through a container restart
 	admin off
 }
